package me.pikanote.companion;
import android.content.*;import android.net.Uri;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.Files;import java.util.*;
final class MemorySharing{
 static JSONObject record(Store store,String id)throws Exception{synchronized(store){JSONObject row=store.find(store.snapshot(),"memories",id);if(row==null)throw new IOException("Memory no longer available");return new JSONObject(row.toString());}}
 static String transcript(Store store,JSONObject row)throws Exception{String text=row.optString("text");if(row.optBoolean("truncated")){String id=row.getString("id");if(!id.matches("m[0-9]+"))throw new IOException("Full transcript is not synchronized yet");File f=store.safeFile(String.format(Locale.ROOT,"note_%03d.txt",Integer.parseInt(id.substring(1))));if(!f.isFile())throw new IOException("Full transcript is not synchronized yet");text=new String(Files.readAllBytes(f.toPath()),StandardCharsets.UTF_8);}return text;}
 static File audio(Store store,JSONObject row)throws Exception{if(row.optBoolean("archived")||row.has("wav")&&!row.optBoolean("wav"))return null;String id=row.getString("id");if(id.matches("m[0-9]+")){File f=store.safeFile(String.format(Locale.ROOT,"note_%03d.wav",Integer.parseInt(id.substring(1))));if(f.isFile())return f;}return store.voiceFile(id);}
 static Uri uri(Context c,File dir,String name){return new Uri.Builder().scheme("content").authority(c.getPackageName()+".memory-share").appendPath(dir.getName()).appendPath(name).build();}
 static Intent prepare(Context c,Store store,String id)throws Exception{JSONObject row=record(store,id);String text=transcript(store,row);File wav=audio(store,row);if(text.isEmpty()&&wav==null)throw new IOException("Transcript and recording are not available yet");File root=new File(c.getCacheDir(),"memory-shares");if(!root.exists()&&!root.mkdirs())throw new IOException("Cannot prepare memory files");File[] old=root.listFiles();if(old!=null)for(File f:old)if(f.getName().matches("[a-f0-9-]{36}")&&System.currentTimeMillis()-f.lastModified()>86400000)PhoneBackup.remove(f);File dir=new File(root,UUID.randomUUID().toString());if(!dir.mkdir())throw new IOException("Cannot prepare memory share");try{ArrayList<Uri> streams=new ArrayList<>();if(!text.isEmpty()){Files.write(new File(dir,"transcript.txt").toPath(),text.getBytes(StandardCharsets.UTF_8));streams.add(uri(c,dir,"transcript.txt"));}if(wav!=null){if(dir.getUsableSpace()<wav.length()+1048576)throw new IOException("Phone storage is full");Files.copy(wav.toPath(),new File(dir,"recording.wav").toPath());streams.add(uri(c,dir,"recording.wav"));}Intent intent=new Intent(streams.size()>1?Intent.ACTION_SEND_MULTIPLE:Intent.ACTION_SEND).setType(streams.size()>1?"*/*":wav!=null?"audio/wav":"text/plain").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION).putExtra(Intent.EXTRA_SUBJECT,row.optString("title","Pika memory"));if(!text.isEmpty())intent.putExtra(Intent.EXTRA_TEXT,text);if(streams.size()>1)intent.putParcelableArrayListExtra(Intent.EXTRA_STREAM,streams);else intent.putExtra(Intent.EXTRA_STREAM,streams.get(0));ClipData clip=new ClipData("Pika memory",wav==null?new String[]{"text/plain"}:text.isEmpty()?new String[]{"audio/wav"}:new String[]{"text/plain","audio/wav"},new ClipData.Item(streams.get(0)));for(int i=1;i<streams.size();i++)clip.addItem(new ClipData.Item(streams.get(i)));intent.setClipData(clip);return intent;}catch(Exception e){PhoneBackup.remove(dir);throw e;}}
}
